#nullable enable // autogenerated

using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Buffs.Entities;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.bubble)]
    public class Bubble : EntityBehaviourDefinition, IDeathEffectsBehaviour
    {
        public Bubble(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_APPLY_STATUS_EFFECT, PostApplyStatusEffectCallback);
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            var buff = entity.AddBuff<FlyBuff>();
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 20f);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (!entity.WillRemoveOnDeath(deathInfo))
            {
                SpawnBubbleBreakParticles(entity);
            }
        }

        public void DeathEffects(Entity entity, DeathInfo deathInfo)
        {
            if (deathInfo.HasEffect(VanillaDamageEffects.SLOW) || deathInfo.HasEffect(VanillaDamageEffects.ICE))
            {
                entity.PlaySound(VanillaSoundID.glassBreak);
                SlowNearbyAllies(entity);
            }
        }
        private void PostApplyStatusEffectCallback(VanillaLevelCallbacks.PostApplyStatusEffectParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var buff = param.buff;
            var buffId = buff.Definition.GetID();
            if (buffId != VanillaBuffID.Enemy.slow && buffId != VanillaBuffID.Entity.frozen)
                return;
            if (!entity.HasBehaviour(this))
                return;
            entity.Die(new DamageEffectList(VanillaDamageEffects.SLOW, VanillaDamageEffects.INSTA_KILL), param.source);
        }
        public static Entity? SpawnBubbleBreakParticles(Entity entity)
        {
            return entity.Level.Spawn(VanillaEffectID.bubbleBreakParticles, entity.GetCenter(), entity);
        }
        public static void SlowNearbyAllies(Entity entity)
        {
            using var collidersItem = ListPool<IEntityCollider>.Rent();
            var colliders = collidersItem.Value;
            slowDetector.DetectMultiple(entity, colliders);
            foreach (var collider in colliders)
            {
                if (!collider.IsForMain())
                    continue;
                collider.Entity.InflictSlow(Ticks.FromSeconds(SLOW_SECONDS), new EntitySourceReference(entity));
            }
        }
        public const float SLOW_SECONDS = 10f;
        private static Detector slowDetector = new SphereDetector(80)
        {
            canDetectInvisible = true,
            factionTarget = FactionTarget.Friendly,
            mask = EntityCollisionHelper.MASK_ENEMY
        };
    }
}
